from datetime import date, timedelta
from typing import Dict, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: Set[str] = set()
        # book_id -> (user, borrow_date)
        self.active_loans: Dict[str, tuple[str, date]] = {}
        # user -> set of book_ids currently borrowed
        self.user_loans: Dict[str, Set[str]] = {}
        # user -> unpaid fines amount
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in library.")
        if book_id in self.active_loans:
            raise ValueError(f"Book '{book_id}' is already borrowed.")

        current_user_loans = self.user_loans.setdefault(user, set())
        if self.unpaid_fines(user) > 0 and len(current_user_loans) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot hold more than one book."
            )

        self.active_loans[book_id] = (user, day)
        current_user_loans.add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if (
            book_id not in self.active_loans
            or self.active_loans[book_id][0] != user
        ):
            raise ValueError(
                f"User '{user}' has not borrowed book '{book_id}'."
            )

        borrowed_user, borrow_date = self.active_loans.pop(book_id)
        self.user_loans[user].remove(book_id)

        due_date = borrow_date + timedelta(days=self.loan_days)
        overdue_days = 0

        # Count overdue weekdays (Monday=0 to Friday=4)
        current = due_date + timedelta(days=1)
        while current <= day:
            if current.weekday() < 5:  # Monday through Friday
                overdue_days += 1
            current += timedelta(days=1)

        fine = overdue_days * self.daily_fine
        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
```

